/**
 * The Skycord mark: the creature's round-topped head wearing headphones, in a
 * 256 x 256 box. Generated by brand/make-mark.mjs; change it there and paste
 * the new strings here.
 *
 * One source for every place the app draws it. Static files that cannot import
 * this (the landing page, the desktop shell's HTML, the Android vectors, the
 * masters in brand/) carry the same numbers; src/__tests__/brandMark.test.ts
 * holds each copy to this module, so a redraw cannot miss one.
 *
 * HEAD is the face without eyes, GEAR the headband and both earcups as one
 * outline; they never overlap. Drawn with the eyes under fill-rule="evenodd"
 * the eyes become holes (MARK). Where the eyes must move or blink, draw HEAD
 * and GEAR solid and paint EYES_AT on top in the background colour instead.
 *
 * The small cut is for 24 px and under: a heavier band, wider gaps and bigger
 * eyes, so nothing closes up on the pixel grid. Colours live in the theme (the
 * accent); the brand's fixed ones are in brand/README.md.
 */
export const VIEWBOX = '0 0 256 256'

export const HEAD = 'M56,150A72,72 0 0 1 200,150V170A48,48 0 0 1 152,218H104A48,48 0 0 1 56,170Z'

export const GEAR =
  'M12,170V130A17,17 0 0 1 26.47,113.19A108,108 0 0 1 229.53,113.19A17,17 0 0 1 244,130V170' +
  'A17,17 0 0 1 210,170V130A17,17 0 0 1 212.99,120.38A90,90 0 0 0 43.01,120.38A17,17 0 0 1 46,130V170' +
  'A17,17 0 0 1 12,170Z'

export const EYES_AT = [
  { cx: 104, cy: 156, r: 14 },
  { cx: 152, cy: 156, r: 14 },
] as const

export const HEAD_SMALL = 'M60,150A68,68 0 0 1 196,150V170A46,46 0 0 1 150,216H106A46,46 0 0 1 60,170Z'

export const GEAR_SMALL =
  'M9,172V128A18,18 0 0 1 23.24,110.4A112,112 0 0 1 232.76,110.4A18,18 0 0 1 247,128V172' +
  'A18,18 0 0 1 211,172V128A18,18 0 0 1 212.86,120.03A90,90 0 0 0 43.14,120.03A18,18 0 0 1 45,128V172' +
  'A18,18 0 0 1 9,172Z'

export const EYES_SMALL_AT = [
  { cx: 103, cy: 156, r: 19 },
  { cx: 153, cy: 156, r: 19 },
] as const

const circle = ({ cx, cy, r }: { cx: number; cy: number; r: number }) =>
  `M${cx - r},${cy}a${r},${r} 0 1 0 ${2 * r},0a${r},${r} 0 1 0 ${-2 * r},0Z`

/** Head, eyes and headphones as one path: fill it with fill-rule="evenodd". */
export const MARK = HEAD + EYES_AT.map(circle).join('') + GEAR
export const MARK_SMALL = HEAD_SMALL + EYES_SMALL_AT.map(circle).join('') + GEAR_SMALL
